    comp:[["Where does the story begin?",["In a London street","In a marsh churchyard on Christmas Eve","On a prison ship","In a rich house"],1,"Pip is visiting his parents' graves when the convict appears."],["Who has raised Pip since his parents died?",["His uncle","His sister Mrs Joe","Miss Havisham","A teacher"],1,"Mrs Joe often reminds him she brought him up 'by hand'."],["What does the convict do when he first sees Pip?",["He runs away","He grabs him and turns him upside down","He asks him for directions","He offers him money"],1,"He wants to frighten Pip into obeying him."],["What two things does the convict demand?",["Money and a boat","A file and food","A map and a knife","A letter and a coat"],1,"He needs the file for the iron on his leg and food because he is starving."],["How does Pip get the food for the convict?",["He buys it","He asks Joe for it","He steals it from the pantry at dawn","Mrs Joe gives it to him"],2,"He takes a pork pie, brandy and bread before anyone wakes."],["Where does Pip find the file?",["In his own room","In the churchyard","In Joe's forge","In the pantry"],2,"Joe keeps his tools in the forge."],["Who does Pip meet on the marsh by mistake?",["Joe","A second convict","Mrs Joe","A soldier"],1,"For a moment Pip thinks he has found the wrong man."],["How does the convict eat the food Pip brings?",["Slowly and politely","Like a hungry dog, very fast","He doesn't eat it","He shares it with the second man"],1,"He is starving after days on the cold marsh."]],
    tf:[["Pip is an orphan.",true,"His parents and five brothers are dead, all buried in the churchyard."],["Joe Gargery is cruel to Pip.",false,"Joe is gentle; it is Mrs Joe who is fierce."],["The convict has escaped from a prison ship.",true,"There is an iron on his leg and his clothes are torn."],["Pip refuses to help the convict.",false,"He is too frightened to refuse."],["Pip steals the file from his own room.",false,"He steals it from Joe's forge."],["The convict eats the food slowly.",false,"He eats it like a hungry dog, very fast."]],
    rw:[["Pip visits the churchyard on Christmas Eve.",0,"Right — that's when the story begins."],["The convict has an iron on his leg.",0,"Right — Pip hears it before he sees him."],["The convict threatens to hurt Pip if he tells anyone.",0,"Right — he speaks of a young man who would find and hurt him."],["Mrs Joe raised Pip 'by hand'.",0,"Right — she says this often, and not kindly."],["Pip tells Joe about the convict that same night.",1,"Wrong — he says nothing, too frightened and ashamed."],["The second convict Pip meets is taller than his own convict.",2,"Doesn't say — Pip only sees him for a moment in the mist."],["The convict asks Pip about the other man on the marsh.",0,"Right — he grows anxious the moment Pip mentions him."],["Pip steals brandy as well as a pie.",0,"Right — he takes both from the pantry."]],
    halves:[["Pip is an orphan","raised by his sister and her husband, the blacksmith Joe."],["While Pip is looking at his parents' graves,","a terrifying man rises up among the gravestones."],["The convict seizes Pip and turns him upside down","before he even asks his name."],["He tells Pip to bring him","a file and something to eat."],["At dawn, before anyone wakes,","Pip creeps down to steal food from the pantry."],["On the misty marsh Pip meets","a second convict who is not the man he is looking for."],["When Pip finds his own convict,","the man eats the stolen food like a hungry animal."],["The moment Pip mentions the other man,","the convict becomes anxious and asks questions."]],
